--- calc.py ---
import csv,re,json,collections
inv={r['id']:float(r['amount']) for r in csv.DictReader(open('invoices.csv',encoding='utf-8'))}
pay=collections.defaultdict(list)
for r in csv.DictReader(open('bank_statement_june.csv',encoding='utf-8')):
    m=re.search(r'inv(?:oice)?[-\s]*(\d{4})',r['memo'],re.I)
    if m and 'INV-'+m.group(1) in inv and float(r['amount'])>0: pay['INV-'+m.group(1)].append(float(r['amount']))
    else: print('skip',r)
un=[i for i in inv if i not in pay]
du=[i for i in pay if len(pay[i])>1]
mm=[{'id':i,'invoiced':inv[i],'paid':round(p[0],2)} for i,p in pay.items() if len(p)==1 and abs(p[0]-inv[i])>0.005]
print(un,du,mm,[(i,pay[i]) for i in du])
json.dump({'unpaid':sorted(un),'duplicated':sorted(du),'mismatched':sorted(mm,key=lambda x:x['id'])},open('../result.json','w'),indent=1)


